// ROCKET — a flag-painted rocket that fights nose-first and fires smaller rockets at you.
//   STRIKE   (attack)          NOSE CONE: the rocket rams its pointed nose out. Forward, up, down; charged for the smash.
//   GIMMICK  (special)         MINI ROCKET: launches a little homing rocket. Costs FUEL, which refills slowly.
//   RECOVERY (up + special)    LIFTOFF: full throttle upward, the exhaust burns anything underneath.
export default function make(api) {
  const { hb, cap, key, mv, spawnProjectile, spriteAnims, spriteLoops, B } = api;

  const stats = {
    weight: 84, walk: 3.0, run: 6.0, dashInit: 7, airSpeed: 4.4, airAccel: 0.22,
    fallSpeed: 6.8, fastFall: 10.5, gravity: 0.42, shortHop: 8, fullHop: 13.5, doubleJump: 12.5,
    jumps: 2, wallJump: false, traction: 0.45, height: 120, width: 44, crouchHeight: 84, landLag: 4, ledgeReach: 40,
  };

  const rest = {};
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, { rot: -lean * 0.4, sx: 0.94, sy: 1.04, dx: -6, ...extra }),
    key(hit, { rot: lean, sx: 1.14, sy: 0.92, dx: 10, ...extra }),
    key(Math.min(total - 1, hit + 6), { rot: lean * 0.7, sx: 1.05, sy: 0.98, dx: 6, ...extra }),
    key(total, rest),
  ];
  const NOSE = { fx: "nose" };
  const FUEL_COST = 34;

  // draws (at the bottom) draw every move; a look only names a hitbox's `fx` and colours its hit sparks
  const looks = {
    missile: { color: "#e8604c" },
    nose: { color: "#ffe680" },
    exhaust: { color: "#e8604c" },
    boom: { color: "#f29a3c" },
  };

  // THE STRIKE: the nose cone. Drawn tip positions (U = 0.4): atk-fwd nose at (73,-28), atk-up nose at (0,-118),
  // atk-down nose at (24,-29) pointing down-forward.
  const STRIKE = { total: 28, hit: 7, active: 5, damage: 12, r: 19 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const start = dir === "u" ? [0, -70] : dir === "d" ? [-8, -64] : dir === "b" ? [-20, -30] : [20, -30];
    const end = dir === "u" ? [0, -126] : dir === "d" ? [30, -20] : dir === "b" ? [-90, -30] : [90, -30];
    const angle = dir === "u" ? 88 : dir === "d" ? 40 : 38;
    const lean = dir === "u" ? -4 : dir === "d" ? 8 : dir === "b" ? -6 : 6;
    const extra = dir === "u" ? { dy: -8, dx: 0 } : dir === "d" ? { dy: 4 } : dir === "b" ? { dx: -10 } : {};
    const cell = dir === "u" ? "atk-up" : dir === "d" ? "atk-down" : "atk-fwd";
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 38, s.growth ?? 85, { ...NOSE, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === "b", ...(s.mv ?? {}) });
  };

  const moves = {
    jab1: aim("jab1", "f", { total: 22, hit: 5, damage: 6, mv: { iasa: 16 } }),
    ftilt: aim("ftilt", "f"),
    dashAttack: aim("dashAttack", "f", { total: 38, hit: 8, active: 6, damage: 12, mv: { motion: [[1, 9, 0], [10, 5, 0], [18, 1, 0]] } }),
    nair: aim("nair", "f", { total: 28, hit: 6, damage: 9, mv: { aerial: true, landingLag: 9 } }),
    fair: aim("fair", "f", { mv: { aerial: true, landingLag: 12 } }),
    bair: aim("bair", "b", { damage: 13, hit: 9, mv: { aerial: true, landingLag: 12 } }),
    utilt: aim("utilt", "u", { damage: 10 }),
    uair: aim("uair", "u", { damage: 10, mv: { aerial: true, landingLag: 10 } }),
    dtilt: aim("dtilt", "d", { damage: 8, total: 26, hit: 7 }),
    dair: aim("dair", "d", { total: 40, hit: 13, damage: 13, hb: { spike: true }, mv: { aerial: true, landingLag: 16 } }),
    // charged: the whole rocket lunges nose-first with the engine lit
    fsmash: mv("fsmash", 50, [
      cap([15, 18], 50, -30, 96, -30, 16, 19, 36, 46, 100, { fx: "boom", priority: 0 }),
      cap([15, 20], 10, -30, 60, -30, 20, 14, 38, 40, 84, { ...NOSE, priority: 1 }),
      cap([15, 20], -20, -30, -70, -30, 18, 8, 150, 30, 50, { fx: "exhaust", group: 1 }),
    ], strikePoses(50, 15, 8), { smash: true, cell: "atk-fwd", motion: [[14, 5, 0], [20, 1, 0]] }),
    usmash: aim("usmash", "u", { total: 48, hit: 14, active: 6, damage: 17, base: 42, growth: 100, mv: { smash: true } }),
    dsmash: mv("dsmash", 52, [
      cap([15, 18], 0, -14, 70, -14, 20, 15, 30, 45, 90, { fx: "exhaust", group: 0 }),
      cap([15, 18], 0, -14, -70, -14, 20, 15, 30, 45, 90, { fx: "exhaust", group: 1 }),
    ], [key(0, { sy: 1.04 }), key(14, { sy: 0.8, sx: 1.2, dy: 4 }), key(22, { sy: 0.84, sx: 1.16 }), key(52, rest)], { smash: true, cell: "idle", fx: "quake" }),
    // GIMMICK, MINI ROCKET: a slow homing rocket that speeds up and explodes
    nspecial: mv("nspecial", 42, [], [key(0, { sy: 0.92, sx: 1.06 }), key(12, { sy: 1.1, sx: 0.94, dy: -4 }), key(22, { sy: 1.0 }), key(42, rest)], { hook: "homer", cell: "atk-up" }),
    // held sideways: a fast straight rocket, no homing
    sspecial: mv("sspecial", 40, [], strikePoses(40, 12, 6), { hook: "dart", cell: "atk-fwd" }),
    // held down: the engine fires in place, a flame burst around the base
    dspecial: mv("dspecial", 50, [
      hb([14, 26], 0, -10, 50, 2, 80, 20, 20, { fx: "exhaust", rehit: 4 }),
      hb([27, 29], 0, -20, 64, 7, 70, 50, 90, { fx: "boom", group: 1 }),
    ], [key(0, { sy: 0.9 }), key(13, { sy: 0.84, sx: 1.12 }), key(14, { sy: 1.12, sx: 0.94, dy: -10 }), key(28, { sy: 1.14, dy: -14 }), key(50, rest)], { hook: "burn", cell: "idle", fx: "quake" }),
    // RECOVERY, LIFTOFF
    uspecial: mv("uspecial", 56, [
      hb([4, 20], 0, 10, 34, 2, 270, 10, 10, { fx: "exhaust", rehit: 4 }),
      cap([8, 12], 0, -80, 0, -126, 16, 6, 85, 50, 70, NOSE),
    ], [key(0, { sy: 0.84, sx: 1.12 }), key(4, { sy: 1.16, sx: 0.9 }), key(30, { sy: 1.08 }), key(56, rest)], { hook: "lift", helpless: true, ledgeOk: true, cell: "atk-up" }),
    ledgeAttack: aim("ledgeAttack", "f", { total: 40, hit: 12, damage: 9 }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 10, -30, 80, -30, 18, 7, 40, 40, 60, { ...NOSE, group: 0 }), cap([20, 23], -10, -30, -80, -30, 18, 7, 40, 40, 60, { ...NOSE, group: 1 })], [key(0, rest), key(12, { dx: 8 }), key(20, { dx: -8 }), key(44, rest)], { cell: "atk-fwd" }),
    taunt: mv("taunt", 56, [], [key(0, rest), key(10, { sy: 0.86, sx: 1.1 }), key(18, { sy: 1.14, dy: -24 }), key(30, { sy: 1.05, dy: -30, rot: 8 }), key(42, { sy: 0.9 }), key(56, rest)], { cell: "atk-up" }),
  };

  // HOW HE'S DRAWN: the nose cone rams out as a white streak with a bow shock folding back off its point, and the
  // engine does the rest in his own flame reds. Cell pixels: the nose tip and the nozzle of each attack cell.
  const INK = "#262626", BLUE = "#3d7cc9", RED = "#e8604c", DEEP = "#c93a1c", ORANGE = "#f29a3c", GOLD = "#ffe680";
  const TIP = { "atk-fwd": [436, 380], "atk-up": [248, 152], "atk-down": [316, 376] };
  const NOZZLE = { "atk-fwd": [262, 372], "atk-up": [255, 335], idle: [256, 360] };
  const STREAK = { color: "#ffffff", ink: INK, core: BLUE };
  const HOT = { color: GOLD, ink: DEEP, core: "#ffffff" };

  // the shock cone: two curved wings folding back off the far end of hitbox i while it's out
  const bowShock = (g, i, size, o = {}) => {
    const { near, far, h } = g.ends(i), [s0, e] = h.frames;
    const t = g.ease(g.span(s0 - 1, s0)), fade = g.span(e, e + (o.lag ?? 5));
    if (t <= 0 || fade >= 1) return;
    const dir = g.angle(near, far), tip = g.toward(far, dir, h.r * 0.9), k = size * t * (1 + fade * 0.4);
    for (const side of [-1, 1]) {
      const wing = [tip, g.toward(tip, dir + 180 + side * 24, k * 0.55), g.toward(tip, dir + 180 + side * 38, k)];
      g.line(wing, { color: o.ink ?? INK, width: 2.6, alpha: 1 - fade });
      g.line([g.toward(wing[1], dir + 180 + side * 70, 6), g.toward(wing[2], dir + 180 + side * 70, 8)], { color: o.ink ?? BLUE, width: 1.6, alpha: 0.7 * (1 - fade) });
    }
  };
  // a nose ram along hitbox i: the streak from the drawn nose, the shock cone, the pop
  const ram = (g, i, o = {}) => {
    const h = g.hit(i), look = o.look ?? STREAK;
    g.thrust(i, { width: o.width ?? h.r * 1.2, lag: o.lag ?? 6, ...look });
    bowShock(g, i, o.shock ?? h.r * 2.2, { ink: look.ink });
    g.pop(i, { n: o.n ?? 7, dist: o.dist ?? 40, ink: o.pop ?? DEEP });
  };
  // the engine kicking: fire from the cell's nozzle back to `tail` (fighter space), lit from frame s to e
  const burn = (g, cell, tail, w, s, e, o = {}) => {
    const lit = g.span(s - 2, s) * (1 - g.span(e, e + (o.lag ?? 6)));
    if (lit <= 0) return;
    const from = g.pose(...NOZZLE[cell]), to = g.lerp(from, g.at(...tail), 0.35 + 0.65 * lit);
    const mark = () => g.flame(to, from, w * (0.5 + 0.5 * lit), { alpha: lit, seed: o.seed ?? s });
    if (o.over) mark(); else g.under(mark);
  };
  // grounded, the exhaust hits the floor and spreads both ways along it
  const splash = (g, reach, w, s, e) => {
    const lit = g.span(s - 2, s) * (1 - g.span(e, e + 8));
    if (lit <= 0) return;
    for (const side of [-1, 1]) g.flame(g.at(side * reach * (0.4 + 0.6 * lit), -6), g.at(side * 6, -4), w * (0.5 + 0.5 * lit), { alpha: lit, seed: s + side * 17 });
  };
  // puffs of exhaust smoke rolling out from p, from frame s
  const smoke = (g, p, s, o = {}) => {
    const t = g.span(s, s + (o.frames ?? 14)), n = o.n ?? 4;
    if (t <= 0 || t >= 1) return;
    for (let k = 0; k < n; k++) {
      const q = g.toward(p, (o.deg ?? 180) + (k - (n - 1) / 2) * (o.spread ?? 30), (o.dist ?? 30) * g.ease(t) * (0.6 + 0.4 * g.noise(k * 7 + s)));
      g.blob(q, (o.r ?? 8) * (0.6 + t), { color: "#ebe6dc", ink: "#a8a092", alpha: 0.75 * (1 - t), seed: k * 19 + s });
    }
  };

  const draws = {
    jab1: (g) => { g.thrust(0, { width: 18, lag: 4, ...STREAK }); g.pop(0, { n: 5, dist: 28, ink: DEEP }); },
    ftilt: (g) => { ram(g, 0); burn(g, "atk-fwd", [-70, -30], 26, 7, 11); },
    dashAttack: (g) => {
      if (g.frame <= 16) g.smear({ count: 4, alpha: 0.45 });
      ram(g, 0, { width: 26, shock: 50 });
      burn(g, "atk-fwd", [-100, -30], 34, 2, 15);
      g.dust(-50, 10, 2, { n: 3 });
    },
    nair: (g) => { ram(g, 0, { width: 20, shock: 34 }); burn(g, "atk-fwd", [-56, -30], 20, 6, 10); },
    fair: (g) => { if (g.hit(0).live) g.smear({ count: 2 }); ram(g, 0, { look: HOT, shock: 46, width: 26 }); burn(g, "atk-fwd", [-80, -30], 30, 7, 12); },
    bair: (g) => { if (g.hit(0).live) g.smear({ count: 2 }); ram(g, 0, { look: HOT, shock: 46, width: 26, pop: INK }); },
    utilt: (g) => { ram(g, 0, { width: 24 }); splash(g, 50, 20, 7, 11); },
    uair: (g) => { ram(g, 0, { width: 24, look: HOT }); burn(g, "atk-up", [0, 30], 30, 7, 11); },
    dtilt: (g) => { ram(g, 0, { width: 20, shock: 34 }); g.dust(20, 60, 8, { n: 3 }); },
    dair: (g) => {
      if (g.frame >= 12 && g.frame <= 18) g.smear({ count: 3, alpha: 0.4 });
      ram(g, 0, { look: HOT, width: 30, shock: 54, n: 10, dist: 56, lag: 8 });
    },
    // the smashes are the engine at full throttle
    fsmash: (g) => {
      if (g.frame >= 14 && g.frame <= 22) g.smear({ count: 4, alpha: 0.5 });
      burn(g, "atk-fwd", [-110, -30], 46, 15, 20, { lag: 10 });
      if (g.frame < 15) burn(g, "atk-fwd", [-50, -30], 10 + g.frame * 1.2, 1, 14, { lag: 0, seed: 3 });
      ram(g, 1, { look: HOT, width: 34, shock: 56, lag: 8 });
      const b = g.ends(0);
      g.burst(b.far, b.h.r * 2.4, g.span(15, 24), { color: GOLD, ink: DEEP, width: 18, n: 12 });
      smoke(g, g.at(-90, -24), 17, { n: 4, dist: 40, r: 10 });
    },
    usmash: (g) => {
      if (g.frame >= 13 && g.frame <= 21) g.smear({ count: 3, alpha: 0.45 });
      ram(g, 0, { look: HOT, width: 34, shock: 60, n: 12, dist: 64, lag: 8 });
      splash(g, 30 + g.span(1, 14) * 60, 34, 14, 19);
      smoke(g, g.at(-20, -4), 15, { deg: 180, n: 3, dist: 44 }); smoke(g, g.at(20, -4), 15, { deg: 0, n: 3, dist: 44 });
    },
    // the engine blasted flat along the floor both ways
    dsmash: (g) => {
      for (const i of [0, 1]) {
        const { near, far, h } = g.ends(i), lit = g.span(13, 15) * (1 - g.span(18, 26));
        if (lit > 0) g.flame(g.lerp(near, g.toward(far, g.angle(near, far), h.r), 0.3 + 0.7 * lit), near, h.r * 2.4 * (0.5 + 0.5 * lit), { alpha: lit, seed: 5 + i * 40 });
      }
      g.dust(40, 110, 15, { n: 3 }); g.dust(-40, -110, 15, { n: 3 });
    },
    // the engine fires in place: fire fanning out round the base, then the blast
    dspecial: (g) => {
      const lit = g.span(12, 15) * (1 - g.span(26, 30));
      if (lit > 0) {
        const from = g.pose(...NOZZLE.idle);
        for (const [x, y, k] of [[-78, -6, 0], [78, -6, 1], [-50, -44, 2], [50, -44, 3]]) g.flame(g.at(x * (0.5 + 0.5 * lit), y), from, 30 * (0.6 + 0.4 * lit), { alpha: lit * (k > 1 ? 0.8 : 1), seed: 9 + k * 31 });
      }
      const b = g.hit(1);
      g.burst([b.x1, b.y1], b.r * 1.2, g.span(27, 36), { color: GOLD, ink: DEEP, width: 22, n: 14 });
      if (g.frame >= 27 && g.frame <= 30) g.blob([b.x1, b.y1 - 10], b.r * (0.7 + 0.1 * (g.frame - 27)), { color: ORANGE, ink: DEEP, alpha: 0.55 - 0.15 * (g.frame - 27), lumpy: 0.4 });
      g.dust(-100, 100, 14, { n: 5 });
      smoke(g, g.at(0, -10), 29, { deg: 90, spread: 50, n: 5, dist: 60, r: 12 });
    },
    // LIFTOFF: full throttle downward, the nose leading the climb
    uspecial: (g) => {
      const h = g.hit(0), lit = g.span(2, 4) * (1 - g.span(20, 28));
      if (lit > 0) {
        const from = g.pose(...NOZZLE["atk-up"]);
        g.under(() => g.flame(g.toward([h.x1, h.y1], 270, h.r * (0.6 + 0.8 * lit)), from, h.r * 1.7, { alpha: lit, seed: 21 }));
      }
      if (g.frame >= 4 && g.frame <= 20) g.smear({ count: 3, alpha: 0.35 });
      ram(g, 1, { width: 24, shock: 40 });
      smoke(g, g.at(0, -4), 4, { deg: 270, spread: 60, n: 5, dist: 40, r: 10 });
    },
    ledgeAttack: (g) => ram(g, 0, { width: 20 }),
    getupAttack: (g) => { ram(g, 0, { width: 18, shock: 32 }); ram(g, 1, { width: 18, shock: 32 }); },
    // the launch: a flash and a puff where the mini rocket leaves (the hook spawns it on frame 12)
    nspecial: (g) => { launch(g, g.at(20, -110), 90); },
    sspecial: (g) => { launch(g, g.at(50, -40), 0); },
    // the mini rocket (a projectile: at() measures from it): the body cut from atk-fwd, turned along its flight,
    // its own engine flickering behind and a smoke trail
    missile: (g) => {
      const c = g.at(0, 0), deg = g.angle(c, [c[0] + g.vx, c[1] + g.vy]), back = deg + 180;
      const fast = Math.min(1, g.dist([0, 0], [g.vx, g.vy]) / 12);
      for (let k = 1; k <= 3; k++) {
        const age = ((g.frame + k * 3) % 9) / 9;
        g.blob(g.toward(c, back, 30 + k * 14 + age * 10), 4 + k * 2 + age * 3, { color: "#ebe6dc", ink: "#a8a092", alpha: 0.6 * (1 - k / 4), seed: k * 13 });
      }
      g.flame(g.toward(c, back, 34 + fast * 18), g.toward(c, back, 18), 13, { seed: 4 });
      g.cell("atk-fwd", c, { crop: [232, 308, 210, 140], size: 44, deg });
    },
  };
  const launch = (g, p, deg) => {
    const t = g.span(12, 26);
    if (t <= 0 || t >= 1) return;
    if (g.frame <= 14) g.blob(p, 12 + (g.frame - 12) * 4, { color: GOLD, ink: DEEP, alpha: 0.9, lumpy: 0.4 });
    g.flecks(p, { t, n: 6, dist: 34, deg: deg + 180, spread: 120, color: DEEP, seed: deg + 3 });
    smoke(g, p, 12, { deg: deg + 180, spread: 50, n: 4, dist: 30, r: 9 });
  };
  for (const id of Object.keys(draws)) if (moves[id]) moves[id].draw = id;

  const fire = (state, f, homing) => {
    const hit = { frames: [0, 999], x: 0, y: 0, r: 16, damage: homing ? 10 : 9, angle: 45, base: homing ? 44 : 36, growth: homing ? 72 : 60 };
    if (f.bars.fuel < FUEL_COST) {
      // out of fuel: it sputters out of the nose and drops
      spawnProjectile(state, f, "missile", f.x + f.moveFacing * 30, f.y - 70, f.moveFacing * 3, -2, 30, { ...hit, damage: 3, base: 20, growth: 20 }, { g: 0.3 });
      return;
    }
    f.bars.fuel -= FUEL_COST;
    if (homing) spawnProjectile(state, f, "missile", f.x + f.moveFacing * 20, f.y - 110, f.moveFacing * 3, -5, 100, hit, { homing: 0.07, homeFrames: 70 });
    else spawnProjectile(state, f, "missile", f.x + f.moveFacing * 50, f.y - 40, f.moveFacing * 12, 0, 60, hit);
  };

  return {
    id: "gen-rocket",
    name: "ROCKET",
    tagline: "Nose first, flag on, never lands gently.",
    stats,
    moves,
    rig: { anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: "#3d7cc9" }, outline: "#262626" },
    looks,
    draws,
    special: () => ({}),
    bars: { fuel: { label: "FUEL", color: "#e8604c", max: 100, start: 100 } },
    hooks: {
      homer: ({ state, f }) => { if (f.frame === 12) fire(state, f, true); },
      dart: ({ state, f }) => { if (f.frame === 12) fire(state, f, false); },
      burn: ({ f }) => {
        // the engine lifts it a little off the ground while it burns
        if (f.frame >= 14 && f.frame <= 26 && !f.grounded) f.vy = Math.min(f.vy, 0.5);
      },
      lift: ({ f, input }) => {
        if (f.frame === 4) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 4 && f.frame <= 32) {
          f.vy = -9 + (f.frame - 4) * 0.22;
          f.vx = (input.x / 100) * 4.2;
        }
      },
    },
    onFrame: ({ f }) => { f.bars.fuel += 0.3; },
    visual: (f) => ({ glow: f.bars.fuel >= 100 ? 0.3 : 0 }),
  };
}
